package com.ridego.backend.controller;
import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api") public class CatalogController {
 private final JdbcTemplate db; public CatalogController(JdbcTemplate db){this.db=db;}
 @GetMapping("/categories") public List<Map<String,Object>> categories(){return db.queryForList("select category_id as id, category_name as name, description, default_daily_rate as defaultDailyRate from car_categories where is_active=1 order by category_name");}
 @GetMapping("/locations") public List<Map<String,Object>> locations(){return db.queryForList("select location_id as id, location_name as name, address, city, country_code as countryCode, phone, opening_hours as openingHours from locations where is_active=1 order by location_name");}
 @GetMapping("/insurance") public List<Map<String,Object>> insurance(){return db.queryForList("select insurance_id as id, insurance_name as name, description, daily_rate as dailyRate from insurance where is_active=1 order by daily_rate");}
 @GetMapping("/cars") public List<Map<String,Object>> cars(@RequestParam(required=false) String category,@RequestParam(required=false) String fuel,@RequestParam(required=false) String transmission,@RequestParam(required=false) java.math.BigDecimal minPrice,@RequestParam(required=false) java.math.BigDecimal maxPrice,@RequestParam(required=false) Long locationId,@RequestParam(required=false) String startDate,@RequestParam(required=false) String endDate){
  String sql="select c.car_id as id,c.slug,c.brand||' '||c.model as name,cc.category_name as category,c.daily_rate as price,c.seats,c.transmission,c.fuel_type as fuel,c.image_url as image,c.description,c.production_year as productionYear,c.color,c.location_id as locationId,c.status from cars c join car_categories cc on cc.category_id=c.category_id where c.is_active=1 and c.status='AVAILABLE' and cc.is_active=1";
  List<Object> p=new ArrayList<>(); if(category!=null&&!category.isBlank()){sql+=" and upper(cc.category_name)=upper(?)";p.add(category);} if(fuel!=null&&!fuel.isBlank()){sql+=" and c.fuel_type=upper(?)";p.add(fuel);} if(transmission!=null&&!transmission.isBlank()){sql+=" and c.transmission=upper(?)";p.add(transmission);} if(minPrice!=null){sql+=" and c.daily_rate>=?";p.add(minPrice);}if(maxPrice!=null){sql+=" and c.daily_rate<=?";p.add(maxPrice);}if(locationId!=null){sql+=" and c.location_id=?";p.add(locationId);}
  if(startDate!=null&&endDate!=null){sql+=" and not exists(select 1 from reservations r where r.car_id=c.car_id and r.status in ('CONFIRMED','IN_PROGRESS') and r.start_date<to_date(?,'YYYY-MM-DD') and r.end_date>to_date(?,'YYYY-MM-DD'))";p.add(endDate);p.add(startDate);}
  sql+=" order by c.daily_rate,c.brand,c.model";return db.queryForList(sql,p.toArray());
 }
 @GetMapping("/cars/{slug}") public Map<String,Object> car(@PathVariable String slug){return db.queryForMap("select c.car_id as id,c.slug,c.brand||' '||c.model as name,cc.category_name as category,c.daily_rate as price,c.seats,c.transmission,c.fuel_type as fuel,c.image_url as image,c.description,c.production_year as productionYear,c.color,c.location_id as locationId,c.deposit_amount as deposit from cars c join car_categories cc on cc.category_id=c.category_id where c.slug=? and c.is_active=1",slug);}
}
